import type { SupportedLocale } from "@/i18n/config";
import type { LocaleFollowup } from "@/i18n/dictionaries/locale-quality-followup";

const c = (description: string, howTo: string, formula: string, exampleNote: string, question: string, answer: string) => ({ description, howTo, formula, exampleNote, faq: { question, answer } });

export const malaysiaPolicyFollowups: Partial<Record<SupportedLocale, LocaleFollowup>> = {
  ko: {
    "malaysia-income-tax-calculator": c("말레이시아 개인소득세 계산기는 거주자 과세소득에 누진 구간을 적용합니다. 엔진의 구간은 LHDN이 게시한 YA 2023–2025 표와 일치하지만, 확인된 자료는 YA 2026 규칙을 확정하지 않습니다. 공제 후 과세소득을 입력하는 단순 참고 계산입니다.", "연간 chargeable income을 MYR로 입력하세요. 총급여를 넣으면 개인 공제·세액공제·환급 조정 전 세금을 계산하게 됩니다.", "각 구간에서 해당 구간에 속하는 금액 × 한계세율을 더합니다. 세율은 최초 RM5,000 0%, 다음 RM15,000 1%, 다음 RM15,000 3%, 이어지는 구간 6%, 11%, 19%, 25%, 26%, 28%, RM2,000,000 초과분 30%입니다.", "YA 2025 표 기준 과세소득 RM100,000은 구간별 세액 합계 RM9,400, 평균세율 9.4%입니다. 엔진 예제도 같은 값을 반환하지만 개인별 감면을 반영한 납부액은 아닙니다.", "이 결과는 2026년 신고 세액인가요?", "확정할 수 없습니다. 확인한 LHDN 표는 YA 2023–2025를 표시합니다. 거주 상태, 개인 공제, 리베이트와 이후 연도 변경도 엔진 입력에 없으므로 결과는 참고치입니다."),
    "malaysia-epf-calculator": c("말레이시아 EPF(KWSP) 계산기는 월급과 연령 구간을 사용해 직원·고용주 분담액을 산술 추정합니다. 기본 구간은 말레이시아 시민 및 특정 영주권자의 비율에 맞지만, 2025년 10월 임금부터 외국인 직원은 별도 2% 비율이 적용될 수 있습니다.", "월급을 MYR로 입력하고 60세 미만 또는 60세 이상을 선택하세요. 시민권·가입 이력·고용 예외는 입력되지 않으므로 해당 범위도 함께 확인해야 합니다.", "엔진은 60세 미만에서 직원 11%, 고용주 RM5,000 이하 13%·초과 12%를 적용합니다. 60세 이상에서는 직원 5.5%, 고용주 5,000 이하 6.5%·초과 6%를 적용합니다.", "월급 RM6,000, 60세 미만이면 직원 RM660, 고용주 RM720, 합계 RM1,380입니다. KWSP 표의 시민·PR 해당 연령 구간과 맞는 산술 예시이며 다른 가입 범주에는 적용하지 마세요.", "외국인 직원도 이 비율인가요?", "아닐 수 있습니다. KWSP 안내상 2025년 10월 임금부터 일정 외국인 직원의 직원·고용주 비율은 각각 2%입니다. 도구에는 시민권 선택이 없어 외국인 급여 계산으로 사용하면 안 됩니다."),
    "malaysia-socso-calculator": c("이 SOCSO(PERKESO) 페이지는 법정 기여표를 구현하지 않습니다. 현재 엔진은 월급의 0.5%를 RM6,000까지 계산하는 단순 직원 몫 예시이며, 실제 SOCSO는 급여 구간표와 가입 범주·연령 조건을 적용합니다.", "월별 insured wages를 MYR로 입력하세요. 결과는 직원 1차 범주의 0.5% 단순 계산이며, 고용주 몫·EIS·보험 적용 자격은 포함하지 않습니다.", "현재 엔진 예시액 = min(월급, RM6,000) × 0.5%. 법정 납부액은 PERKESO의 실제 급여 구간표로 정해지므로 비례식만으로 대체할 수 없습니다.", "월급 RM6,000에서 엔진은 RM30을 표시합니다. PERKESO Act 4 표의 RM5,900 초과~RM6,000 구간 직원 부담은 RM29.75입니다. RM30은 엔진 산술 예시일 뿐 실제 납부액이 아닙니다.", "이 숫자를 급여 공제에 사용해도 되나요?", "안 됩니다. 고정 비율은 표의 반올림 구간과 2차 범주·면제 규칙을 구현하지 않습니다. 급여 공제에는 PERKESO의 최신 기여표와 고용주 계산기를 사용하세요."),
  },
  en: {
    "malaysia-income-tax-calculator": c("This Malaysia income-tax calculator applies progressive bands to entered annual chargeable income. Its schedule matches the LHDN table shown for YA 2023–2025; the reviewed source does not establish YA 2026 rules. Treat it as a resident-rate illustration, not a filed-tax result.", "Enter annual chargeable income in MYR after applicable reliefs if known. Entering gross salary estimates tax before personal reliefs and rebates.", "For each marginal band, multiply the income slice by its rate and add the slices: 0% on the first RM5,000, then 1%, 3%, 6%, 11%, 19%, 25%, 26%, 28%, and 30% above RM2 million.", "At RM100,000 of chargeable income, the YA 2025 schedule gives RM9,400 tax and a 9.4% average rate. The engine returns the same values; it does not apply personal reliefs or rebates.", "Is this my final 2026 tax bill?", "No. The checked LHDN schedule lists YA 2023–2025, not a confirmed YA 2026 schedule. Residency, reliefs, rebates, and later changes are also outside the inputs."),
    "malaysia-epf-calculator": c("This Malaysia EPF (KWSP) calculator estimates employee and employer shares from monthly wages and a broad age band. Its default rates match the listed Malaysian employee categories, but some foreign employees have separate 2% shares for wages from October 2025.", "Enter monthly wages in MYR and choose below 60 or 60 and above. Citizenship, prior membership, and exemptions are not asked, so confirm that the selected schedule applies.", "The engine uses employee 11% below 60 and employer 13% at wages up to RM5,000 or 12% above. At 60+, it uses 5.5% employee and 6.5%/6% employer rates around RM5,000.", "At RM6,000 monthly wages below age 60, the engine returns RM660 employee, RM720 employer, RM1,380 total. This matches that rate category's arithmetic, not every member category.", "Do foreign employees use these rates?", "Not all. KWSP states that certain non-Malaysian employees have 2% employee and 2% employer shares effective for October 2025 wages. The calculator has no citizenship option and should not estimate those cases."),
    "malaysia-socso-calculator": c("This SOCSO (PERKESO) page does not implement the statutory contribution table. The current engine shows a simple employee-side 0.5% calculation capped at RM6,000; actual contributions use wage bands and eligibility/category rules.", "Enter monthly insured wages in MYR. The result is only the engine's simple 0.5% employee illustration; employer share, EIS, and coverage eligibility are not included.", "Current engine illustration = min(monthly wages, RM6,000) × 0.5%. The legal amount is selected from PERKESO's wage-band table, so this percentage formula is not a substitute.", "At RM6,000 monthly wages, the engine returns RM30. PERKESO's Act 4 table lists RM29.75 employee contribution for the band above RM5,900 through RM6,000. The engine result is illustrative, not a payroll deduction.", "Can I use this amount for payroll withholding?", "No. A flat percentage misses table rounding and category or exemption rules. Use PERKESO's current contribution table or official employer calculator for payroll."),
  },
  ja: {
    "malaysia-income-tax-calculator": c("マレーシア所得税計算機は、入力した年間課税所得に累進税率を適用します。エンジンの税率表はLHDNが掲載するYA 2023–2025の表と一致しますが、確認した資料はYA 2026の規則を確定しません。居住者向け税率の参考計算です。", "適用できる控除後の年間課税所得をMYRで入力します。総給与を入力すると個人控除や税額控除前の概算になります。", "各限界税率区分の所得部分に税率を掛けて合算します。最初のRM5,000は0%、以降1%、3%、6%、11%、19%、25%、26%、28%、RM2,000,000超は30%です。", "課税所得RM100,000ではYA 2025表の税額はRM9,400、平均税率は9.4%です。エンジンも同額ですが、個人控除やリベートは適用しません。", "これは2026年の確定税額ですか？", "いいえ。確認したLHDN表はYA 2023–2025で、YA 2026を確認できていません。居住区分、控除、リベートやその後の変更も入力にありません。"),
    "malaysia-epf-calculator": c("マレーシアEPF（KWSP）計算機は月給と大まかな年齢区分から従業員・雇用主の拠出を推定します。標準率は記載されたマレーシア人区分に合いますが、外国人従業員には2025年10月賃金から別の各2%率が適用される場合があります。", "月給をMYRで入力し、60歳未満か60歳以上を選びます。国籍、加入履歴、免除は選べないため適用対象を確認してください。", "エンジンは60歳未満で従業員11%、雇用主はRM5,000以下13%・超は12%。60歳以上は従業員5.5%、雇用主6.5%または6%です。", "60歳未満で月給RM6,000なら従業員RM660、雇用主RM720、合計RM1,380です。この率区分の算術例であり、全加入者に当てはまるとは限りません。", "外国人従業員にもこの率が適用されますか？", "一律ではありません。KWSPによると一定の外国人従業員は2025年10月賃金から双方2%です。計算機には国籍欄がないため、そのケースには使えません。"),
    "malaysia-socso-calculator": c("このSOCSO（PERKESO）ページは法定の拠出表を実装していません。現行エンジンは月給RM6,000を上限に従業員分0.5%を単純計算しますが、実際は賃金帯の表と加入区分・資格条件で決まります。", "月間の被保険賃金をMYRで入力します。結果はエンジンの単純な従業員0.5%例で、雇用主負担、EIS、適用資格は含みません。", "現行エンジン例＝min（月給, RM6,000）×0.5%。法定額はPERKESOの賃金帯表から決まるため、この比例式では代用できません。", "月給RM6,000ではエンジンはRM30を返します。PERKESO Act 4表でRM5,900超～RM6,000の従業員負担はRM29.75です。RM30は給与控除額ではなく例示値です。", "この額を給与控除に使えますか？", "使えません。固定率では表の丸めや区分・免除規則を再現しません。給与計算ではPERKESOの最新表または公式雇用主向け計算機を確認してください。"),
  },
  zh: {
    "malaysia-income-tax-calculator": c("马来西亚个人所得税计算器对输入的年度应课税收入应用累进税率。引擎税阶与LHDN公布的YA 2023–2025表一致，但已核对资料未确认YA 2026规则；结果是居民税率的计算示例。", "以MYR输入年度应课税收入；若已知，可先扣除适用减免。直接输入工资总额会得到未扣个人减免和税款回扣前的估算。", "各税阶按该阶收入部分乘以边际税率后相加：首RM5,000为0%，随后为1%、3%、6%、11%、19%、25%、26%、28%，超过RM2,000,000部分为30%。", "应课税收入RM100,000按YA 2025税阶计算为RM9,400，平均税率9.4%。引擎结果一致，但未计个人减免和回扣。", "这是我2026年的最终税款吗？", "不是。已核对的LHDN表列出YA 2023–2025，未确认YA 2026。居住身份、个人减免、回扣和之后的规则变化也不在输入中。"),
    "malaysia-epf-calculator": c("马来西亚EPF（KWSP）计算器根据月薪和宽泛年龄组估算雇员及雇主份额。默认费率适用于所列马来西亚员工类别；但部分外籍员工自2025年10月工资起适用双方各2%的不同费率。", "以MYR输入月薪，选择60岁以下或60岁及以上。工具不询问国籍、加入记录或豁免情况，请先确认适用类别。", "引擎对60岁以下使用雇员11%；雇主在工资不超过RM5,000时13%，超过时12%。60岁及以上为雇员5.5%、雇主6.5%或6%。", "60岁以下月薪RM6,000时，雇员RM660、雇主RM720、合计RM1,380。该示例只匹配这一费率类别的算术。", "外籍员工也适用这些费率吗？", "不一定。KWSP说明部分非马来西亚员工自2025年10月工资起双方各缴2%。计算器没有国籍选项，不应估算这些情况。"),
    "malaysia-socso-calculator": c("此SOCSO（PERKESO）页面没有实现法定供款表。当前引擎仅按工资的0.5%计算雇员示例，并以RM6,000封顶；实际金额按工资分档表、类别和资格规则确定。", "以MYR输入每月受保工资。结果只是引擎的雇员0.5%算术示例，不含雇主份额、EIS或保障资格判断。", "当前引擎示例＝min（月工资，RM6,000）×0.5%。法定供款额须按PERKESO工资分档表读取，不能用此比例公式替代。", "月工资RM6,000时引擎显示RM30。PERKESO Act 4表中，RM5,900以上至RM6,000档的雇员供款为RM29.75。RM30只是模型示例，不是工资扣款额。", "能把这个数用于工资扣款吗？", "不能。固定比例无法复现分档取整、供款类别或豁免规则。实际工资处理请用PERKESO最新供款表或官方雇主计算器。"),
  },
  es: {
    "malaysia-income-tax-calculator": c("Esta calculadora del impuesto sobre la renta de Malasia aplica tramos progresivos al ingreso imponible anual introducido. Los tramos del motor coinciden con la tabla de LHDN para YA 2023–2025, pero la fuente revisada no confirma las reglas de YA 2026; es una ilustración para residentes.", "Introduce el ingreso imponible anual en MYR, después de las deducciones aplicables si las conoces. Si introduces el salario bruto, el cálculo no resta alivios personales ni créditos.", "Se suma cada porción de ingreso por su tipo marginal: 0 % sobre los primeros RM5.000 y luego 1 %, 3 %, 6 %, 11 %, 19 %, 25 %, 26 %, 28 % y 30 % sobre el exceso de RM2.000.000.", "Con RM100.000 de ingreso imponible, la tabla YA 2025 produce RM9.400 de impuesto y una tasa media del 9,4 %. El motor coincide, pero no aplica alivios ni reembolsos personales.", "¿Es mi impuesto final de 2026?", "No. La tabla LHDN consultada muestra YA 2023–2025, no confirma YA 2026. Residencia fiscal, alivios, rebajas y cambios posteriores tampoco forman parte de las entradas."),
    "malaysia-epf-calculator": c("La calculadora EPF (KWSP) de Malasia estima las partes del trabajador y empleador a partir del salario mensual y un grupo de edad amplio. Las tasas predeterminadas corresponden a categorías habituales de ciudadanos malasios; algunos trabajadores extranjeros tienen tasas distintas del 2 % por parte desde los salarios de octubre de 2025.", "Introduce el salario mensual en MYR y elige menos de 60 o 60 años o más. No se pregunta ciudadanía, historial de afiliación ni exenciones; comprueba qué categoría aplica.", "El motor usa 11 % del empleado menor de 60; empleador 13 % hasta RM5.000 y 12 % por encima. Desde 60 años usa 5,5 % del empleado y 6,5 %/6 % del empleador.", "Con RM6.000 al mes y menos de 60 años, calcula RM660 del empleado y RM720 del empleador, RM1.380 en total. Es un ejemplo aritmético de esa categoría, no de todas.", "¿Se aplican estas tasas a trabajadores extranjeros?", "No a todos. KWSP indica que ciertos trabajadores no malasios tienen aportaciones del 2 % por cada parte desde los salarios de octubre de 2025. No hay selector de ciudadanía, así que no uses esta herramienta para ellos."),
    "malaysia-socso-calculator": c("Esta página de SOCSO (PERKESO) no implementa la tabla legal de contribuciones. El motor actual muestra un cálculo simple del 0,5 % de la parte del empleado, con tope salarial de RM6.000; el importe legal depende de bandas salariales y reglas de categoría y elegibilidad.", "Introduce el salario mensual asegurado en MYR. El resultado solo ilustra el 0,5 % del empleado; no incluye la parte patronal, EIS ni la elegibilidad de cobertura.", "Ilustración actual del motor = min(salario mensual, RM6.000) × 0,5 %. La cantidad legal se consulta en la tabla salarial de PERKESO; la fórmula proporcional no la sustituye.", "Con RM6.000 mensuales, el motor devuelve RM30. La tabla Act 4 de PERKESO indica RM29,75 de aportación del empleado para el tramo superior a RM5.900 y hasta RM6.000. RM30 es una ilustración, no una deducción de nómina.", "¿Puedo usarlo para retener el importe en nómina?", "No. El porcentaje fijo no reproduce los tramos redondeados ni las categorías y exenciones. Para nómina, usa la tabla vigente o la calculadora oficial para empleadores de PERKESO."),
  },
  "pt-br": {
    "malaysia-income-tax-calculator": c("Esta calculadora do imposto de renda da Malásia aplica faixas progressivas à renda tributável anual informada. As faixas do mecanismo coincidem com a tabela LHDN de YA 2023–2025, mas a fonte consultada não confirma as regras de YA 2026; o resultado é uma ilustração para residentes.", "Informe a renda tributável anual em MYR, já descontadas as deduções aplicáveis se conhecidas. Se informar o salário bruto, o cálculo não deduz benefícios pessoais nem créditos.", "Some cada parcela de renda pela alíquota marginal: 0% nos primeiros RM5.000, depois 1%, 3%, 6%, 11%, 19%, 25%, 26%, 28% e 30% sobre o que exceder RM2.000.000.", "Com renda tributável de RM100.000, a tabela YA 2025 resulta em RM9.400 de imposto e alíquota média de 9,4%. O mecanismo coincide, mas não aplica benefícios nem abatimentos pessoais.", "Este é meu imposto final de 2026?", "Não. A tabela LHDN consultada mostra YA 2023–2025 e não confirma YA 2026. Residência fiscal, benefícios, abatimentos e mudanças posteriores também não fazem parte das entradas."),
    "malaysia-epf-calculator": c("A calculadora EPF (KWSP) da Malásia estima as parcelas do empregado e do empregador a partir do salário mensal e de uma faixa etária ampla. As taxas padrão correspondem a categorias comuns de cidadãos malaios; certos trabalhadores estrangeiros têm taxas diferentes de 2% para cada parte desde os salários de outubro de 2025.", "Informe o salário mensal em MYR e escolha abaixo de 60 ou 60 anos ou mais. Cidadania, histórico de adesão e isenções não são perguntados; confirme a categoria aplicável.", "O mecanismo usa 11% do empregado abaixo de 60; empregador 13% até RM5.000 e 12% acima. A partir de 60, usa 5,5% do empregado e 6,5%/6% do empregador.", "Com RM6.000 por mês e menos de 60 anos, calcula RM660 do empregado e RM720 do empregador, total RM1.380. É um exemplo aritmético dessa categoria, não de todos os membros.", "Essas taxas valem para trabalhadores estrangeiros?", "Não para todos. A KWSP informa que determinados estrangeiros contribuem com 2% cada desde os salários de outubro de 2025. Como não há seletor de cidadania, não use a ferramenta nesses casos."),
    "malaysia-socso-calculator": c("Esta página SOCSO (PERKESO) não implementa a tabela legal de contribuições. O mecanismo atual mostra apenas 0,5% da parcela do empregado, limitado a RM6.000; o valor legal depende de faixas salariais, categoria e elegibilidade.", "Informe o salário segurado mensal em MYR. O resultado é só a ilustração de 0,5% do empregado; não inclui parcela patronal, EIS nem a análise da cobertura.", "Ilustração atual = min(salário mensal, RM6.000) × 0,5%. O valor legal é obtido na tabela salarial da PERKESO; essa fórmula proporcional não a substitui.", "Para RM6.000 mensais, o mecanismo retorna RM30. A tabela Act 4 da PERKESO lista RM29,75 de contribuição do empregado na faixa acima de RM5.900 até RM6.000. RM30 é apenas ilustrativo, não desconto de folha.", "Posso usar o resultado para desconto em folha?", "Não. O percentual fixo não reproduz as faixas arredondadas nem as regras de categoria e isenção. Para folha, consulte a tabela vigente ou a calculadora oficial para empregadores da PERKESO."),
  },
  de: {
    "malaysia-income-tax-calculator": c("Dieser malaysische Einkommensteuerrechner wendet progressive Stufen auf das eingegebene jährliche steuerpflichtige Einkommen an. Die Engine entspricht der LHDN-Tabelle für YA 2023–2025; die geprüfte Quelle bestätigt keine Regeln für YA 2026. Das Ergebnis ist eine Illustration für Steueransässige.", "Geben Sie das jährliche steuerpflichtige Einkommen in MYR ein, nach möglichen Freibeträgen, sofern bekannt. Bei Bruttogehalt bleiben persönliche Entlastungen und Steuergutschriften unberücksichtigt.", "Die Teilbeträge jeder Grenzsteuerstufe werden addiert: 0% auf die ersten RM5.000, danach 1%, 3%, 6%, 11%, 19%, 25%, 26%, 28% und 30% über RM2.000.000.", "Bei RM100.000 steuerpflichtigem Einkommen ergeben die YA-2025-Stufen RM9.400 Steuer und 9,4% Durchschnittssatz. Die Engine stimmt überein, wendet aber keine persönlichen Entlastungen oder Ermäßigungen an.", "Ist das meine endgültige Steuer für 2026?", "Nein. Die geprüfte LHDN-Tabelle zeigt YA 2023–2025 und bestätigt YA 2026 nicht. Ansässigkeit, Freibeträge, Rabatte und spätere Änderungen sind ebenfalls nicht als Eingaben enthalten."),
    "malaysia-epf-calculator": c("Der malaysische EPF-Rechner (KWSP) schätzt Arbeitnehmer- und Arbeitgeberanteile anhand des Monatslohns und einer groben Altersgruppe. Die Standardraten passen zu üblichen malaysischen Arbeitnehmerkategorien; für bestimmte ausländische Beschäftigte gelten seit Löhnen für Oktober 2025 abweichende Anteile von je 2%.", "Geben Sie den Monatslohn in MYR ein und wählen Sie unter 60 oder ab 60 Jahren. Staatsangehörigkeit, Mitgliedschaftsverlauf und Ausnahmen werden nicht abgefragt.", "Die Engine nutzt unter 60 11% Arbeitnehmeranteil und 13% Arbeitgeber bis RM5.000, darüber 12%. Ab 60 gelten 5,5% Arbeitnehmeranteil und 6,5%/6% Arbeitgeberanteil.", "Bei RM6.000 Monatslohn unter 60 berechnet sie RM660 vom Arbeitnehmer und RM720 vom Arbeitgeber, zusammen RM1.380. Das Beispiel gilt nur für diese Beitragskategorie.", "Gelten diese Sätze auch für ausländische Arbeitnehmer?", "Nicht für alle. KWSP nennt für bestimmte nichtmalaysische Beschäftigte je 2% ab den Löhnen für Oktober 2025. Da kein Staatsangehörigkeitsfeld existiert, ist dieser Rechner dafür ungeeignet."),
    "malaysia-socso-calculator": c("Diese SOCSO-Seite (PERKESO) bildet die gesetzliche Beitragstabelle nicht ab. Die aktuelle Engine zeigt eine einfache Arbeitnehmerrechnung mit 0,5% und einer Lohnobergrenze von RM6.000; der tatsächliche Betrag folgt Lohnstufen und Regeln zur Kategorie und Berechtigung.", "Geben Sie den monatlichen versicherten Lohn in MYR ein. Das Ergebnis ist nur die 0,5%-Illustration für Beschäftigte; Arbeitgeberanteil, EIS und Versicherungsberechtigung fehlen.", "Aktuelle Engine-Illustration = min(Monatslohn, RM6.000) × 0,5%. Der gesetzliche Betrag wird aus PERKESO-Lohnstufen abgelesen; diese Prozentformel ersetzt sie nicht.", "Bei RM6.000 Monatslohn liefert die Engine RM30. Die PERKESO-Tabelle nach Act 4 nennt RM29,75 Arbeitnehmerbeitrag für mehr als RM5.900 bis RM6.000. RM30 ist kein korrekter Lohnabzug.", "Kann ich den Betrag für die Lohnabrechnung verwenden?", "Nein. Der feste Satz bildet weder gerundete Stufen noch Kategorien und Ausnahmen ab. Verwenden Sie für die Lohnabrechnung die aktuelle PERKESO-Tabelle oder den offiziellen Arbeitgeberrechner."),
  },
  fr: {
    "malaysia-income-tax-calculator": c("Ce calculateur d’impôt sur le revenu malaisien applique des tranches progressives au revenu imposable annuel saisi. Le barème du moteur correspond à celui de LHDN pour YA 2023–2025 ; la source consultée ne confirme pas les règles de YA 2026. Il s’agit d’une illustration pour résidents.", "Saisissez le revenu imposable annuel en MYR, après les déductions applicables si elles sont connues. Un salaire brut ne sera pas diminué des allègements ou crédits personnels.", "Additionnez chaque part de revenu selon son taux marginal : 0 % sur les premiers RM5 000, puis 1 %, 3 %, 6 %, 11 %, 19 %, 25 %, 26 %, 28 % et 30 % au-delà de RM2 000 000.", "Pour RM100 000 imposables, le barème YA 2025 donne RM9 400 d’impôt et un taux moyen de 9,4 %. Le moteur concorde, sans appliquer les allègements ni réductions personnels.", "Est-ce mon impôt définitif de 2026 ?", "Non. Le barème LHDN vérifié couvre YA 2023–2025 et ne confirme pas YA 2026. Résidence fiscale, allègements, remises et changements ultérieurs ne sont pas non plus dans les entrées."),
    "malaysia-epf-calculator": c("Le calculateur EPF (KWSP) malaisien estime les parts du salarié et de l’employeur à partir du salaire mensuel et d’une large tranche d’âge. Les taux par défaut correspondent aux catégories malaisiennes courantes ; certains travailleurs étrangers ont des taux séparés de 2 % chacun depuis les salaires d’octobre 2025.", "Saisissez le salaire mensuel en MYR et choisissez moins de 60 ans ou 60 ans et plus. Nationalité, historique d’adhésion et exemptions ne sont pas demandés.", "Le moteur applique 11 % au salarié de moins de 60 ans ; l’employeur verse 13 % jusqu’à RM5 000 et 12 % au-delà. À partir de 60 ans : 5,5 % salarié et 6,5 %/6 % employeur.", "À RM6 000 par mois avant 60 ans, le moteur calcule RM660 pour le salarié et RM720 pour l’employeur, soit RM1 380. Cet exemple concerne uniquement cette catégorie.", "Ces taux s’appliquent-ils aux salariés étrangers ?", "Pas à tous. KWSP indique que certains non-Malaisiens cotisent à 2 % chacun depuis les salaires d’octobre 2025. Sans champ de nationalité, cet outil ne convient pas à ces cas."),
    "malaysia-socso-calculator": c("Cette page SOCSO (PERKESO) ne reproduit pas le barème légal de cotisation. Le moteur actuel affiche un calcul simple de 0,5 % côté salarié, plafonné à RM6 000 ; le montant réel dépend des tranches de salaire, de la catégorie et de l’éligibilité.", "Saisissez le salaire mensuel assuré en MYR. Le résultat illustre seulement les 0,5 % salarié ; part employeur, EIS et critères de couverture sont exclus.", "Illustration actuelle = min(salaire mensuel, RM6 000) × 0,5 %. Le montant légal se lit dans le barème salarial PERKESO ; cette formule proportionnelle ne le remplace pas.", "À RM6 000 par mois, le moteur renvoie RM30. Le tableau PERKESO Act 4 indique RM29,75 à la charge du salarié pour la tranche supérieure à RM5 900 jusqu’à RM6 000. RM30 n’est pas une retenue de paie correcte.", "Puis-je utiliser ce résultat pour la paie ?", "Non. Le taux fixe ne reproduit pas l’arrondi des tranches ni les catégories et exemptions. Pour la paie, consultez le barème actuel ou le calculateur employeur officiel de PERKESO."),
  },
  vi: {
    "malaysia-income-tax-calculator": c("Máy tính thuế thu nhập Malaysia áp dụng các bậc lũy tiến cho thu nhập chịu thuế năm bạn nhập. Biểu mức trong công cụ khớp bảng LHDN YA 2023–2025; nguồn đã kiểm tra chưa xác nhận quy định YA 2026. Đây là ví dụ cho cư dân thuế.", "Nhập thu nhập chịu thuế cả năm bằng MYR, sau các khoản giảm trừ phù hợp nếu đã biết. Nhập lương gộp sẽ chưa trừ ưu đãi hay tín dụng thuế cá nhân.", "Cộng từng phần thu nhập theo thuế suất biên: 0% cho RM5.000 đầu tiên, tiếp theo 1%, 3%, 6%, 11%, 19%, 25%, 26%, 28% và 30% cho phần vượt RM2.000.000.", "Thu nhập chịu thuế RM100.000 theo bảng YA 2025 cho thuế RM9.400 và thuế suất bình quân 9,4%. Kết quả công cụ khớp nhưng chưa tính giảm trừ hay hoàn thuế cá nhân.", "Đây có phải thuế cuối cùng năm 2026 không?", "Không. Bảng LHDN đã kiểm tra chỉ liệt kê YA 2023–2025, chưa xác nhận YA 2026. Tình trạng cư trú, giảm trừ, hoàn thuế và thay đổi sau đó cũng không có trong đầu vào."),
    "malaysia-epf-calculator": c("Máy tính EPF (KWSP) Malaysia ước tính phần đóng của người lao động và chủ lao động từ lương tháng và nhóm tuổi rộng. Mức mặc định khớp một số nhóm nhân viên Malaysia phổ biến; một số lao động nước ngoài có mức riêng 2% mỗi bên từ lương tháng 10/2025.", "Nhập lương tháng bằng MYR và chọn dưới 60 hoặc từ 60 tuổi. Công cụ không hỏi quốc tịch, lịch sử tham gia hay diện miễn trừ.", "Công cụ áp dụng nhân viên dưới 60 tuổi 11%; chủ lao động 13% nếu lương đến RM5.000, 12% nếu cao hơn. Từ 60 tuổi: nhân viên 5,5%, chủ lao động 6,5%/6%.", "Lương RM6.000/tháng dưới 60 tuổi cho kết quả nhân viên RM660, chủ lao động RM720, tổng RM1.380. Ví dụ chỉ phù hợp nhóm mức đóng này.", "Lao động nước ngoài có dùng các mức này không?", "Không phải tất cả. KWSP nêu một số lao động không phải người Malaysia đóng 2% mỗi bên từ lương tháng 10/2025. Công cụ không có lựa chọn quốc tịch nên không phù hợp trường hợp đó."),
    "malaysia-socso-calculator": c("Trang SOCSO (PERKESO) này chưa triển khai bảng đóng góp theo luật. Động cơ hiện tại chỉ minh họa 0,5% phần người lao động, giới hạn lương RM6.000; số tiền thực tế phụ thuộc bậc lương, nhóm tham gia và điều kiện.", "Nhập tiền lương được bảo hiểm mỗi tháng bằng MYR. Kết quả chỉ là minh họa 0,5% phía người lao động; không gồm phần chủ lao động, EIS hay xét điều kiện bảo hiểm.", "Minh họa hiện tại = min(lương tháng, RM6.000) × 0,5%. Mức luật định được tra theo bảng bậc lương PERKESO; không thể thay bằng công thức tỷ lệ này.", "Với lương RM6.000, công cụ trả RM30. Bảng PERKESO Act 4 ghi phần người lao động RM29,75 cho bậc trên RM5.900 đến RM6.000. RM30 là ví dụ của động cơ, không phải khấu trừ lương chính xác.", "Có thể dùng kết quả để khấu trừ bảng lương không?", "Không. Tỷ lệ cố định bỏ qua làm tròn theo bậc và quy tắc nhóm/miễn trừ. Hãy dùng bảng hiện hành hoặc máy tính chính thức dành cho chủ lao động của PERKESO."),
  },
  id: {
    "malaysia-income-tax-calculator": c("Kalkulator pajak penghasilan Malaysia menerapkan tarif progresif pada pendapatan kena pajak tahunan yang dimasukkan. Tabel mesin cocok dengan jadwal LHDN YA 2023–2025; sumber yang diperiksa belum memastikan aturan YA 2026. Hasilnya merupakan ilustrasi tarif bagi penduduk pajak.", "Masukkan pendapatan kena pajak tahunan dalam MYR setelah keringanan yang berlaku jika diketahui. Gaji bruto belum dikurangi keringanan atau kredit pajak pribadi.", "Jumlahkan setiap bagian pendapatan menurut tarif marginal: 0% untuk RM5.000 pertama, lalu 1%, 3%, 6%, 11%, 19%, 25%, 26%, 28%, dan 30% atas bagian di atas RM2.000.000.", "Pendapatan kena pajak RM100.000 menghasilkan pajak RM9.400 dan tarif rata-rata 9,4% menurut tabel YA 2025. Mesin cocok, tetapi tidak menerapkan keringanan atau pengurangan pribadi.", "Apakah ini tagihan pajak final saya untuk 2026?", "Bukan. Jadwal LHDN yang diperiksa mencantumkan YA 2023–2025, bukan aturan YA 2026 yang terkonfirmasi. Status residensi, keringanan, rabat, dan perubahan selanjutnya juga tidak dimodelkan."),
    "malaysia-epf-calculator": c("Kalkulator EPF (KWSP) Malaysia memperkirakan bagian pekerja dan pemberi kerja dari gaji bulanan dan kelompok usia umum. Tarif bawaan sesuai kategori karyawan Malaysia tertentu; sebagian pekerja asing memiliki tarif 2% per pihak untuk gaji sejak Oktober 2025.", "Masukkan gaji bulanan dalam MYR dan pilih di bawah 60 atau 60 tahun ke atas. Kewarganegaraan, riwayat kepesertaan, dan pengecualian tidak ditanyakan.", "Mesin memakai 11% pekerja di bawah 60; pemberi kerja 13% hingga RM5.000 dan 12% di atasnya. Mulai usia 60: pekerja 5,5%, pemberi kerja 6,5%/6%.", "Gaji RM6.000 per bulan di bawah usia 60 menghasilkan RM660 pekerja dan RM720 pemberi kerja, total RM1.380. Ini contoh aritmetika untuk kategori tersebut saja.", "Apakah pekerja asing juga memakai tarif ini?", "Tidak semuanya. KWSP menyebut pekerja non-Malaysia tertentu membayar 2% untuk masing-masing pihak sejak gaji Oktober 2025. Tidak ada pilihan kewarganegaraan, jadi jangan gunakan kalkulator untuk kasus itu."),
    "malaysia-socso-calculator": c("Halaman SOCSO (PERKESO) ini belum menerapkan tabel kontribusi menurut undang-undang. Mesin saat ini hanya memberi ilustrasi 0,5% bagian pekerja dengan batas gaji RM6.000; jumlah resmi mengikuti pita upah, kategori, dan kelayakan.", "Masukkan upah bulanan yang diasuransikan dalam MYR. Hasil hanya ilustrasi 0,5% pekerja; bagian pemberi kerja, EIS, dan kelayakan pertanggungan tidak dihitung.", "Ilustrasi mesin = min(upah bulanan, RM6.000) × 0,5%. Jumlah hukum diambil dari tabel pita upah PERKESO; rumus persentase ini bukan penggantinya.", "Pada upah RM6.000, mesin menghasilkan RM30. Tabel PERKESO Act 4 mencantumkan kontribusi pekerja RM29,75 untuk pita di atas RM5.900 sampai RM6.000. RM30 bukan potongan gaji yang tepat.", "Bolehkah angka ini dipakai untuk pemotongan payroll?", "Tidak. Persentase tetap tidak mencerminkan pembulatan pita, kategori, atau pengecualian. Gunakan tabel terbaru atau kalkulator resmi pemberi kerja PERKESO."),
  },
  th: {
    "malaysia-income-tax-calculator": c("เครื่องคำนวณภาษีเงินได้มาเลเซียใช้ขั้นอัตราก้าวหน้ากับเงินได้พึงประเมินรายปีที่กรอก ตารางในระบบตรงกับ LHDN YA 2023–2025 แต่แหล่งที่ตรวจยังไม่ยืนยันกฎ YA 2026 จึงเป็นเพียงตัวอย่างอัตราสำหรับผู้มีถิ่นที่อยู่ทางภาษี", "กรอกเงินได้พึงประเมินรายปีเป็น MYR หลังหักสิทธิลดหย่อนที่ทราบแล้ว หากกรอกเงินเดือนรวม ระบบยังไม่หักสิทธิหรือเครดิตภาษีส่วนบุคคล", "รวมเงินแต่ละส่วนตามอัตราขั้นบันได: 0% สำหรับ RM5,000 แรก จากนั้น 1%, 3%, 6%, 11%, 19%, 25%, 26%, 28% และ 30% สำหรับส่วนเกิน RM2,000,000", "เงินได้พึงประเมิน RM100,000 ตามตาราง YA 2025 มีภาษี RM9,400 และอัตราเฉลี่ย 9.4% ระบบให้ค่าเดียวกันแต่ยังไม่รวมสิทธิส่วนบุคคล", "นี่คือภาษีสุดท้ายปี 2026 หรือไม่?", "ไม่ ตาราง LHDN ที่ตรวจระบุ YA 2023–2025 และยังไม่ยืนยัน YA 2026 สถานะถิ่นที่อยู่ สิทธิลดหย่อน เงินคืน และการเปลี่ยนแปลงภายหลังก็ไม่อยู่ในข้อมูลนำเข้า"),
    "malaysia-epf-calculator": c("เครื่องคำนวณ EPF (KWSP) มาเลเซียประมาณส่วนของลูกจ้างและนายจ้างจากเงินเดือนและกลุ่มอายุแบบกว้าง อัตราเริ่มต้นตรงกับพนักงานมาเลเซียบางประเภท แต่ลูกจ้างต่างชาติบางกลุ่มใช้อัตรา 2% ต่อฝ่ายตั้งแต่เงินเดือนตุลาคม 2025", "กรอกเงินเดือนรายเดือนเป็น MYR แล้วเลือกอายุต่ำกว่า 60 หรือ 60 ปีขึ้นไป ระบบไม่ถามสัญชาติ ประวัติการเป็นสมาชิก หรือข้อยกเว้น", "ระบบใช้ลูกจ้างต่ำกว่า 60 ปี 11%; นายจ้าง 13% เมื่อเงินเดือนไม่เกิน RM5,000 และ 12% เมื่อเกิน จากอายุ 60 ปีใช้ลูกจ้าง 5.5%, นายจ้าง 6.5%/6%", "เงินเดือน RM6,000 ต่อเดือนและอายุต่ำกว่า 60 ให้ลูกจ้าง RM660 นายจ้าง RM720 รวม RM1,380 เป็นตัวอย่างเฉพาะประเภทนี้", "ลูกจ้างต่างชาติใช้อัตรานี้ด้วยไหม?", "ไม่ใช่ทุกคน KWSP ระบุว่าลูกจ้างที่ไม่ใช่มาเลเซียบางประเภทจ่าย 2% ต่อฝ่ายตั้งแต่เงินเดือนตุลาคม 2025 เครื่องมือไม่มีช่องสัญชาติ จึงไม่เหมาะกับกรณีนั้น"),
    "malaysia-socso-calculator": c("หน้านี้ยังไม่ได้ใช้ตารางเงินสมทบ SOCSO (PERKESO) ตามกฎหมาย เครื่องปัจจุบันแสดงตัวอย่างส่วนลูกจ้าง 0.5% และจำกัดฐานที่ RM6,000; ยอดจริงขึ้นกับช่วงค่าจ้าง ประเภท และคุณสมบัติ", "กรอกค่าจ้างที่เอาประกันรายเดือนเป็น MYR ผลลัพธ์เป็นเพียงตัวอย่าง 0.5% ของลูกจ้าง ไม่รวมส่วนของนายจ้าง EIS หรือการตรวจสิทธิ", "ตัวอย่างของเครื่องปัจจุบัน = min(ค่าจ้างรายเดือน, RM6,000) × 0.5% ยอดตามกฎหมายต้องดูตารางช่วงค่าจ้าง PERKESO สูตรเปอร์เซ็นต์นี้ใช้แทนไม่ได้", "ค่าจ้าง RM6,000 ทำให้เครื่องแสดง RM30 ตาราง PERKESO Act 4 ระบุส่วนลูกจ้าง RM29.75 สำหรับช่วงเกิน RM5,900 ถึง RM6,000 ค่า RM30 เป็นตัวอย่างของระบบ ไม่ใช่ยอดหักเงินเดือนที่ถูกต้อง", "ใช้ตัวเลขนี้หักเงินเดือนจริงได้ไหม?", "ไม่ได้ อัตราคงที่ไม่สะท้อนการปัดเศษตามช่วง ประเภท หรือข้อยกเว้น ให้ใช้ตารางล่าสุดหรือเครื่องคำนวณทางการของ PERKESO สำหรับนายจ้าง"),
  },
  "zh-tw": {
    "malaysia-income-tax-calculator": c("馬來西亞所得稅計算器會對輸入的年度應課稅所得套用累進稅階。引擎稅階符合LHDN公布的YA 2023–2025表格，但已查來源尚未確認YA 2026規則，因此僅供居民稅率參考。", "以MYR輸入年度應課稅所得；若已知，先扣除適用減免。輸入總薪資時，結果尚未扣個人減免或稅額抵免。", "逐級計算各段所得後相加：首RM5,000為0%，接續為1%、3%、6%、11%、19%、25%、26%、28%，超過RM2,000,000部分為30%。", "YA 2025稅階下，RM100,000應課稅所得的稅額為RM9,400，平均稅率9.4%。引擎結果相符，但未套用個人減免或退稅。", "這是我2026年的最終稅額嗎？", "不是。查到的LHDN表列出YA 2023–2025，尚未確認YA 2026。居住身分、減免、回扣及後續變更也不在輸入中。"),
    "malaysia-epf-calculator": c("馬來西亞EPF（KWSP）計算器依月薪和粗略年齡區間估算員工與雇主份額。預設費率適用於部分常見馬來西亞員工類別；某些外籍員工自2025年10月薪資起雙方各採2%費率。", "以MYR輸入月薪，選擇未滿60歲或60歲以上。工具不詢問國籍、會員紀錄或豁免資格。", "引擎對未滿60歲使用員工11%；雇主在RM5,000以下13%、超過12%。60歲以上使用員工5.5%、雇主6.5%/6%。", "未滿60歲、月薪RM6,000時，員工RM660、雇主RM720，合計RM1,380。此算例只對應該費率類別。", "外籍員工也用這些費率嗎？", "不一定。KWSP指出部分非馬來西亞員工自2025年10月薪資起雙方各為2%。計算器沒有國籍選項，不適用於這些情況。"),
    "malaysia-socso-calculator": c("本SOCSO（PERKESO）頁面尚未實作法定供款表。現行引擎僅以月薪的0.5%示範員工份額，並以RM6,000為上限；實際金額依薪資級距、供款類別及資格規則計算。", "以MYR輸入每月受保薪資。結果只是引擎的員工0.5%示例，不含雇主份額、EIS或投保資格判定。", "現行引擎示例＝min（月薪，RM6,000）×0.5%。法定金額需查PERKESO薪資級距表，不能用此比例公式替代。", "月薪RM6,000時引擎顯示RM30。PERKESO Act 4表列出超過RM5,900至RM6,000級距的員工供款為RM29.75。RM30只是模型示例，不是正確薪資扣款。", "可以用這個數字作為薪資扣款嗎？", "不可以。固定比例未依級距取整，也未處理類別或豁免。實際薪資作業請查閱PERKESO最新供款表或官方雇主計算器。"),
  },
  it: {
    "malaysia-income-tax-calculator": c("Questo calcolatore dell’imposta sul reddito malese applica scaglioni progressivi al reddito imponibile annuo inserito. Le fasce corrispondono alla tabella LHDN per YA 2023–2025; la fonte verificata non conferma le regole YA 2026. È un’illustrazione per residenti fiscali.", "Inserisci il reddito imponibile annuo in MYR, al netto delle agevolazioni applicabili se note. Inserendo lo stipendio lordo non vengono sottratte agevolazioni o crediti personali.", "Somma ogni quota di reddito alla relativa aliquota marginale: 0% sui primi RM5.000, poi 1%, 3%, 6%, 11%, 19%, 25%, 26%, 28% e 30% oltre RM2.000.000.", "Con RM100.000 imponibili, la tabella YA 2025 produce RM9.400 di imposta e un’aliquota media del 9,4%. Il motore coincide ma non applica agevolazioni o rimborsi personali.", "È la mia imposta definitiva per il 2026?", "No. La tabella LHDN consultata mostra YA 2023–2025 e non conferma YA 2026. Residenza fiscale, agevolazioni, rimborsi e modifiche successive non sono inclusi."),
    "malaysia-epf-calculator": c("Il calcolatore EPF (KWSP) malese stima le quote di lavoratore e datore di lavoro da stipendio mensile e fascia d’età ampia. Le aliquote predefinite valgono per categorie comuni di cittadini malesi; alcuni lavoratori stranieri hanno aliquote separate del 2% ciascuno sui salari da ottobre 2025.", "Inserisci lo stipendio mensile in MYR e scegli sotto i 60 anni o dai 60 anni. Nazionalità, iscrizione precedente ed esenzioni non sono richieste.", "Il motore applica 11% al lavoratore sotto i 60; il datore versa 13% fino a RM5.000 e 12% oltre. Dai 60 anni: 5,5% lavoratore e 6,5%/6% datore.", "Con RM6.000 mensili e meno di 60 anni, il motore calcola RM660 dal lavoratore e RM720 dal datore, totale RM1.380. L’esempio riguarda solo quella categoria.", "Le stesse aliquote valgono per i lavoratori stranieri?", "Non per tutti. KWSP indica che alcuni non malesi versano il 2% ciascuno sui salari da ottobre 2025. Manca la scelta della nazionalità, quindi il calcolatore non va usato per quei casi."),
    "malaysia-socso-calculator": c("Questa pagina SOCSO (PERKESO) non implementa la tabella legale dei contributi. Il motore attuale mostra solo un semplice 0,5% a carico del dipendente, con tetto salariale RM6.000; l’importo reale dipende da fasce, categoria e requisiti.", "Inserisci il salario mensile assicurato in MYR. Il risultato illustra solo lo 0,5% del dipendente; non include quota datoriale, EIS o verifica della copertura.", "Illustrazione attuale = min(salario mensile, RM6.000) × 0,5%. L’importo legale si legge nella tabella salariale PERKESO; la formula proporzionale non la sostituisce.", "A RM6.000 il motore mostra RM30. La tabella PERKESO Act 4 indica RM29,75 a carico del dipendente nella fascia oltre RM5.900 fino a RM6.000. RM30 è una dimostrazione, non una trattenuta corretta.", "Posso usare il risultato per la busta paga?", "No. Il tasso fisso non riproduce gli arrotondamenti per fascia né categorie ed esenzioni. Per le paghe consulta la tabella aggiornata o il calcolatore ufficiale PERKESO per datori di lavoro."),
  },
  nl: {
    "malaysia-income-tax-calculator": c("Deze Maleisische inkomstenbelastingcalculator past progressieve schijven toe op het ingevoerde jaarlijkse belastbare inkomen. De engine komt overeen met de LHDN-tabel voor YA 2023–2025; de gecontroleerde bron bevestigt YA 2026 niet. Het is een illustratie voor belastinginwoners.", "Voer het jaarlijkse belastbare inkomen in MYR in, na toepasselijke aftrekposten indien bekend. Bij invoer van brutoloon worden persoonlijke tegemoetkomingen en kredieten niet afgetrokken.", "Tel elke inkomensschijf tegen het marginale tarief op: 0% over de eerste RM5.000, daarna 1%, 3%, 6%, 11%, 19%, 25%, 26%, 28% en 30% boven RM2.000.000.", "Bij RM100.000 belastbaar inkomen bedraagt de belasting volgens YA 2025 RM9.400 en het gemiddelde tarief 9,4%. De engine geeft hetzelfde, zonder persoonlijke tegemoetkomingen of kortingen.", "Is dit mijn definitieve belasting voor 2026?", "Nee. De gecontroleerde LHDN-tabel vermeldt YA 2023–2025 en bevestigt YA 2026 niet. Fiscale woonplaats, tegemoetkomingen, kortingen en latere wijzigingen vallen ook buiten de invoer."),
    "malaysia-epf-calculator": c("De Maleisische EPF-calculator (KWSP) schat werknemers- en werkgeversbijdragen op basis van maandloon en een brede leeftijdsgroep. De standaardtarieven gelden voor gebruikelijke Maleisische werknemerscategorieën; sommige buitenlandse werknemers hebben vanaf loon van oktober 2025 aparte aandelen van elk 2%.", "Voer het maandloon in MYR in en kies jonger dan 60 of 60 en ouder. Nationaliteit, lidmaatschapsgeschiedenis en vrijstellingen worden niet gevraagd.", "De engine gebruikt 11% werknemer onder 60; werkgever 13% tot RM5.000 en 12% daarboven. Vanaf 60 geldt 5,5% werknemer en 6,5%/6% werkgever.", "Bij RM6.000 maandloon onder 60 berekent de engine RM660 werknemer en RM720 werkgever, samen RM1.380. Dit voorbeeld past alleen bij die bijdragecategorie.", "Gelden deze tarieven ook voor buitenlandse werknemers?", "Niet voor iedereen. KWSP noemt voor bepaalde niet-Maleisische werknemers 2% per partij vanaf loon van oktober 2025. Er is geen nationaliteitskeuze, dus gebruik de tool niet voor die gevallen."),
    "malaysia-socso-calculator": c("Deze SOCSO-pagina (PERKESO) implementeert de wettelijke bijdrageTabel niet. De huidige engine toont alleen 0,5% werknemersbijdrage met een loonplafond van RM6.000; de echte bijdrage volgt loonschijven, categorie en toelatingsregels.", "Voer het maandelijkse verzekerde loon in MYR in. De uitkomst illustreert alleen 0,5% werknemer; werkgeversdeel, EIS en dekkingstoets ontbreken.", "Huidige engine-illustratie = min(maandloon, RM6.000) × 0,5%. Het wettelijke bedrag volgt uit PERKESO-loonschijven; deze procentformule vervangt de tabel niet.", "Bij RM6.000 loon geeft de engine RM30. De PERKESO Act 4-tabel noemt RM29,75 werknemersbijdrage voor de schijf boven RM5.900 tot RM6.000. RM30 is geen correcte looninhouding.", "Kan ik dit bedrag voor de loonadministratie gebruiken?", "Nee. Het vaste percentage verwerkt afronding per schijf, categorieën en vrijstellingen niet. Gebruik voor de loonadministratie de actuele PERKESO-tabel of officiële werkgeverscalculator."),
  },
  hi: {
    "malaysia-income-tax-calculator": c("यह मलेशिया आयकर कैलकुलेटर दर्ज वार्षिक करयोग्य आय पर प्रगतिशील स्लैब लगाता है। इंजन की दरें LHDN की YA 2023–2025 तालिका से मेल खाती हैं, लेकिन जाँचा गया स्रोत YA 2026 के नियम की पुष्टि नहीं करता; यह निवासी दरों का उदाहरण है।", "यदि ज्ञात हो तो लागू राहत घटाकर वार्षिक करयोग्य आय MYR में डालें। सकल वेतन डालने पर निजी राहत और क्रेडिट घटाए नहीं जाते।", "हर सीमांत स्लैब की आय पर दर लगाकर जोड़ें: पहले RM5,000 पर 0%, फिर 1%, 3%, 6%, 11%, 19%, 25%, 26%, 28%, और RM2,000,000 से ऊपर 30%।", "RM100,000 करयोग्य आय पर YA 2025 तालिका RM9,400 कर और 9.4% औसत दर देती है। इंजन मेल खाता है, पर निजी राहत या छूट लागू नहीं करता।", "क्या यह 2026 का अंतिम कर है?", "नहीं। जाँची गई LHDN तालिका YA 2023–2025 दिखाती है, YA 2026 की पुष्टि नहीं। कर-निवास, राहत, रिबेट और बाद के बदलाव भी इनपुट में नहीं हैं।"),
    "malaysia-epf-calculator": c("मलेशिया EPF (KWSP) कैलकुलेटर मासिक वेतन और व्यापक आयु समूह से कर्मचारी तथा नियोक्ता अंश का अनुमान लगाता है। डिफ़ॉल्ट दरें कुछ सामान्य मलेशियाई कर्मचारी श्रेणियों से मेल खाती हैं; कुछ विदेशी कर्मचारियों पर अक्टूबर 2025 वेतन से प्रत्येक पक्ष का अलग 2% लागू है।", "मासिक वेतन MYR में भरें और 60 से कम या 60 और अधिक चुनें। नागरिकता, सदस्यता इतिहास और छूट नहीं पूछी जाती।", "इंजन 60 से कम आयु में कर्मचारी 11%; नियोक्ता RM5,000 तक 13%, उससे ऊपर 12% लगाता है। 60 से अधिक में कर्मचारी 5.5% और नियोक्ता 6.5%/6%।", "60 से कम आयु और RM6,000 मासिक वेतन पर कर्मचारी RM660, नियोक्ता RM720, कुल RM1,380 आता है। यह उसी योगदान श्रेणी का उदाहरण है।", "क्या विदेशी कर्मचारी भी यही दरें देते हैं?", "सभी नहीं। KWSP के अनुसार कुछ गैर-मलेशियाई कर्मचारियों के लिए अक्टूबर 2025 वेतन से दोनों पक्ष 2% देते हैं। कैलकुलेटर में नागरिकता विकल्प नहीं, इसलिए उस स्थिति में इसका उपयोग न करें।"),
    "malaysia-socso-calculator": c("यह SOCSO (PERKESO) पृष्ठ वैधानिक योगदान तालिका लागू नहीं करता। मौजूदा इंजन केवल कर्मचारी पक्ष का सरल 0.5% और RM6,000 वेतन सीमा दिखाता है; वास्तविक राशि वेतन-बैंड, श्रेणी और पात्रता पर निर्भर करती है।", "मासिक बीमित वेतन MYR में दर्ज करें। परिणाम केवल कर्मचारी के 0.5% का उदाहरण है; नियोक्ता अंश, EIS और पात्रता शामिल नहीं हैं।", "मौजूदा इंजन उदाहरण = min(मासिक वेतन, RM6,000) × 0.5%। वैधानिक राशि PERKESO की वेतन-बैंड तालिका से आती है; यह अनुपात सूत्र उसका विकल्प नहीं है।", "RM6,000 वेतन पर इंजन RM30 दिखाता है। PERKESO Act 4 तालिका RM5,900 से अधिक और RM6,000 तक के बैंड में कर्मचारी योगदान RM29.75 बताती है। RM30 पेरोल कटौती का सही मान नहीं है।", "क्या मैं इसे पेरोल कटौती के लिए उपयोग कर सकता हूँ?", "नहीं। स्थिर प्रतिशत बैंड राउंडिंग, श्रेणी या छूट नियम नहीं दर्शाता। पेरोल के लिए PERKESO की मौजूदा तालिका या नियोक्ता का आधिकारिक कैलकुलेटर देखें।"),
  },
  ru: {
    "malaysia-income-tax-calculator": c("Калькулятор подоходного налога Малайзии применяет прогрессивные ступени к введённому годовому облагаемому доходу. Таблица движка совпадает с таблицей LHDN для YA 2023–2025; проверенный источник не подтверждает правила YA 2026. Это иллюстрация ставок для резидентов.", "Введите годовой облагаемый доход в MYR после применимых льгот, если они известны. При вводе валовой зарплаты личные льготы и налоговые кредиты не вычитаются.", "Сложите части дохода по предельным ставкам: 0% на первые RM5 000, затем 1%, 3%, 6%, 11%, 19%, 25%, 26%, 28% и 30% сверх RM2 000 000.", "При облагаемом доходе RM100 000 таблица YA 2025 даёт налог RM9 400 и среднюю ставку 9,4%. Движок совпадает, но личные льготы и возвраты не применяет.", "Это окончательный налог за 2026 год?", "Нет. Проверенная таблица LHDN включает YA 2023–2025 и не подтверждает YA 2026. Резидентство, льготы, возвраты и последующие изменения также не введены."),
    "malaysia-epf-calculator": c("Калькулятор EPF (KWSP) Малайзии оценивает доли работника и работодателя по месячной зарплате и широкой возрастной группе. Стандартные ставки подходят отдельным обычным категориям граждан Малайзии; для некоторых иностранных работников с зарплаты за октябрь 2025 действуют отдельные доли по 2%.", "Введите месячную зарплату в MYR и выберите возраст до 60 или от 60 лет. Гражданство, история участия и освобождения не запрашиваются.", "Движок использует 11% работника до 60 лет; работодатель — 13% до RM5 000 и 12% выше. С 60 лет: 5,5% работника и 6,5%/6% работодателя.", "При зарплате RM6 000 и возрасте до 60 лет получится RM660 работника и RM720 работодателя, всего RM1 380. Это пример только для данной категории.", "Эти ставки применяются к иностранным работникам?", "Не ко всем. KWSP указывает для некоторых не-малайзийцев по 2% с каждой стороны начиная с зарплаты за октябрь 2025. В калькуляторе нет выбора гражданства, поэтому эти случаи не моделируются."),
    "malaysia-socso-calculator": c("Эта страница SOCSO (PERKESO) не реализует установленную законом таблицу взносов. Текущий движок показывает упрощённые 0,5% работника с ограничением зарплаты RM6 000; фактическая сумма зависит от диапазона, категории и права на страхование.", "Введите месячную страхуемую зарплату в MYR. Результат — только иллюстрация 0,5% работника; доля работодателя, EIS и проверка покрытия не включены.", "Иллюстрация движка = min(месячная зарплата, RM6 000) × 0,5%. Законная сумма берётся из таблицы зарплатных диапазонов PERKESO; эта пропорция её не заменяет.", "При RM6 000 движок показывает RM30. Таблица PERKESO Act 4 указывает RM29,75 работника для диапазона свыше RM5 900 до RM6 000. RM30 — иллюстрация, а не корректное удержание.", "Можно ли использовать результат для расчёта зарплаты?", "Нет. Фиксированный процент не отражает округление по диапазонам, категории или освобождения. Для зарплаты используйте актуальную таблицу либо официальный калькулятор работодателя PERKESO."),
  },
  tr: {
    "malaysia-income-tax-calculator": c("Malezya gelir vergisi hesaplayıcısı, girilen yıllık vergiye tabi gelire artan oranlı dilimler uygular. Motorun tarifesi LHDN'nin YA 2023–2025 tablosuyla uyumludur; incelenen kaynak YA 2026 kurallarını doğrulamıyor. Sonuç, vergi mukimleri için bir tarife örneğidir.", "Biliniyorsa uygulanabilir indirimlerden sonraki yıllık vergiye tabi geliri MYR cinsinden girin. Brüt maaş girilirse kişisel indirim ve krediler düşülmez.", "Her marjinal dilimdeki gelir parçasını oranıyla çarpıp toplayın: ilk RM5.000 için %0, ardından %1, %3, %6, %11, %19, %25, %26, %28 ve RM2.000.000 üzeri için %30.", "RM100.000 vergiye tabi gelir, YA 2025 tablosunda RM9.400 vergi ve %9,4 ortalama oran verir. Motor eşleşir; kişisel indirim ve iadeleri uygulamaz.", "Bu 2026 yılı için kesin vergi borcum mu?", "Hayır. Kontrol edilen LHDN tablosu YA 2023–2025'i gösteriyor ve YA 2026'yı doğrulamıyor. Vergi ikameti, indirimler, iadeler ve sonraki değişiklikler de girdilerde yok."),
    "malaysia-epf-calculator": c("Malezya EPF (KWSP) hesaplayıcısı aylık ücret ve geniş bir yaş bandıyla çalışan ve işveren payını tahmin eder. Varsayılan oranlar yaygın bazı Malezyalı çalışan kategorilerine uyar; bazı yabancı çalışanlarda Ekim 2025 ücretlerinden başlayarak her taraf için ayrı %2 oran vardır.", "Aylık ücreti MYR olarak girin ve 60 yaş altı ya da 60 ve üzerini seçin. Vatandaşlık, üyelik geçmişi ve muafiyetler sorulmaz.", "Motor 60 yaş altında çalışan için %11; işveren için RM5.000'e kadar %13, üstünde %12 kullanır. 60 yaş ve üzerinde çalışan %5,5, işveren %6,5/%6'dır.", "60 yaş altında RM6.000 aylık ücret için çalışan RM660, işveren RM720, toplam RM1.380 hesaplanır. Örnek yalnızca bu katkı kategorisine uygundur.", "Yabancı çalışanlar da bu oranları mı kullanır?", "Hepsi değil. KWSP, bazı Malezyalı olmayan çalışanlar için Ekim 2025 ücretlerinden itibaren her iki tarafın %2 ödeyeceğini belirtiyor. Vatandaşlık seçeneği olmadığından bu aracı o durumlarda kullanmayın."),
    "malaysia-socso-calculator": c("Bu SOCSO (PERKESO) sayfası yasal katkı tablosunu uygulamaz. Mevcut motor yalnızca çalışan payını %0,5 ve RM6.000 ücret tavanını kullanarak gösterir; gerçek tutar ücret dilimine, kategoriye ve uygunluğa bağlıdır.", "Aylık sigortalı ücreti MYR cinsinden girin. Sonuç sadece çalışanın %0,5'lik örneğidir; işveren payı, EIS ve kapsam uygunluğu dahil değildir.", "Mevcut motor örneği = min(aylık ücret, RM6.000) × %0,5. Yasal tutar PERKESO ücret dilimi tablosundan alınır; bu oran formülü tablonun yerini tutmaz.", "RM6.000 ücrette motor RM30 döndürür. PERKESO Act 4 tablosu RM5.900 üzeri–RM6.000 aralığında çalışan payını RM29,75 gösterir. RM30 doğru bordro kesintisi değildir.", "Bu sonucu bordro kesintisi için kullanabilir miyim?", "Hayır. Sabit yüzde, dilim yuvarlamasını ve kategori/muafiyet kurallarını göstermez. Bordro için güncel PERKESO tablosu veya işveren hesaplayıcısını kullanın."),
  },
  pl: {
    "malaysia-income-tax-calculator": c("Kalkulator podatku dochodowego Malezji stosuje progresywne progi do podanego rocznego dochodu podlegającego opodatkowaniu. Tabela silnika odpowiada tabeli LHDN dla YA 2023–2025; sprawdzone źródło nie potwierdza zasad YA 2026. To ilustracja stawek dla rezydentów.", "Wpisz roczny dochód do opodatkowania w MYR po znanych ulgach. Przy wpisaniu wynagrodzenia brutto nie są odejmowane ulgi ani kredyty osobiste.", "Zsumuj części dochodu według stawki krańcowej: 0% od pierwszych RM5 000, dalej 1%, 3%, 6%, 11%, 19%, 25%, 26%, 28% oraz 30% od nadwyżki ponad RM2 000 000.", "Przy RM100 000 dochodu opodatkowanego tabela YA 2025 daje RM9 400 podatku i 9,4% średniej stawki. Silnik się zgadza, ale nie stosuje ulg i zwrotów osobistych.", "Czy to mój ostateczny podatek za 2026 rok?", "Nie. Sprawdzona tabela LHDN obejmuje YA 2023–2025 i nie potwierdza YA 2026. Rezydencja podatkowa, ulgi, zwroty i późniejsze zmiany również nie są wejściami."),
    "malaysia-epf-calculator": c("Malezyjski kalkulator EPF (KWSP) szacuje udziały pracownika i pracodawcy na podstawie miesięcznej pensji i szerokiej grupy wieku. Stawki domyślne pasują do typowych kategorii obywateli Malezji; część pracowników zagranicznych ma od wynagrodzeń za październik 2025 odrębne stawki po 2%.", "Wpisz miesięczną pensję w MYR i wybierz poniżej 60 lub od 60 lat. Narzędzie nie pyta o obywatelstwo, historię członkostwa ani zwolnienia.", "Silnik stosuje 11% pracownika poniżej 60 lat; pracodawca 13% do RM5 000 i 12% powyżej. Od 60 lat: pracownik 5,5%, pracodawca 6,5%/6%.", "Przy RM6 000 miesięcznie i wieku poniżej 60 lat wynik to RM660 pracownika i RM720 pracodawcy, razem RM1 380. To przykład tylko dla tej kategorii.", "Czy pracownicy zagraniczni mają te same stawki?", "Nie wszyscy. KWSP podaje dla części osób niebędących obywatelami Malezji po 2% od wynagrodzeń za październik 2025. Brak pola obywatelstwa sprawia, że kalkulator nie obejmuje tych przypadków."),
    "malaysia-socso-calculator": c("Ta strona SOCSO (PERKESO) nie wdraża ustawowej tabeli składek. Obecny silnik pokazuje wyłącznie proste 0,5% pracownika z limitem podstawy RM6 000; rzeczywista kwota zależy od przedziału płac, kategorii i uprawnień.", "Wpisz miesięczne wynagrodzenie ubezpieczone w MYR. Wynik to jedynie ilustracja 0,5% pracownika; nie obejmuje udziału pracodawcy, EIS ani kwalifikacji do ochrony.", "Bieżąca ilustracja silnika = min(miesięczna płaca, RM6 000) × 0,5%. Ustawową kwotę odczytuje się z tabeli przedziałów PERKESO; wzór procentowy jej nie zastępuje.", "Przy RM6 000 silnik pokazuje RM30. Tabela PERKESO Act 4 podaje RM29,75 składki pracownika dla przedziału powyżej RM5 900 do RM6 000. RM30 nie jest poprawnym potrąceniem płacowym.", "Czy mogę użyć tego wyniku do listy płac?", "Nie. Stały procent pomija zaokrąglenia przedziałów oraz reguły kategorii i zwolnień. Do płac użyj aktualnej tabeli lub oficjalnego kalkulatora pracodawcy PERKESO."),
  },
  fil: {
    "malaysia-income-tax-calculator": c("Gumagamit ang calculator na ito ng progresibong tax bracket ng Malaysia para sa taunang taxable income. Tugma ang naka-code na mga bracket sa talahanayan ng LHDN para sa YA 2023–2025; hindi kinukumpirma ng nasuring source ang YA 2026. Halimbawa lamang ito ng rate para sa resident taxpayers.", "Ilagay ang taunang taxable income sa MYR pagkatapos ng mga naaangkop na relief kung alam ang mga ito. Hindi awtomatikong ibinabawas ang personal relief at rebate kapag gross salary ang inilagay.", "Kuwentahin ang bawat bahagi ng kita sa marginal rate nito: 0% sa unang RM5,000, kasunod ang 1%, 3%, 6%, 11%, 19%, 25%, 26%, 28%, at 30% sa lampas RM2,000,000.", "Sa taxable income na RM100,000, ang YA 2025 bands ay nagbibigay ng RM9,400 na buwis at 9.4% average rate. Pareho ang engine, ngunit walang personal relief o rebate.", "Ito ba ang pinal kong buwis para sa 2026?", "Hindi. YA 2023–2025 lamang ang nasa talahanayan ng LHDN na nasuri; hindi nito pinatutunayan ang YA 2026. Hindi rin kasama ang tax residency, relief, rebate, at mga susunod na pagbabago."),
    "malaysia-epf-calculator": c("Tinataya ng Malaysia EPF (KWSP) calculator ang bahagi ng empleyado at employer gamit ang buwanang sahod at malawak na age band. Ang default rates ay para sa ilang karaniwang kategorya ng Malaysian members; may hiwalay na 2% share para sa ilang foreign employees mula sa sahod ng Oktubre 2025.", "Ilagay ang buwanang sahod sa MYR at piliin ang wala pang 60 o 60 pataas. Hindi tinatanong ang citizenship, dating membership, o exemption.", "Gumagamit ang engine ng 11% employee rate kung wala pang 60; employer rate na 13% hanggang RM5,000 at 12% lampas dito. Sa edad 60 pataas: 5.5% employee at 6.5%/6% employer.", "Sa RM6,000 buwanang sahod at wala pang 60, RM660 ang employee, RM720 ang employer, at RM1,380 ang kabuuan. Para lamang ito sa ipinakitang contribution category.", "Pareho ba ito para sa foreign workers?", "Hindi sa lahat. May ilang non-Malaysian employees na may 2% employee at employer share mula sa sahod ng Oktubre 2025. Walang citizenship option ang calculator kaya hindi nito saklaw ang mga kasong iyon."),
    "malaysia-socso-calculator": c("Hindi ginagamit ng SOCSO (PERKESO) page na ito ang statutory contribution table. Ipinapakita lamang ng kasalukuyang engine ang simpleng 0.5% employee share hanggang RM6,000 na sahod; nakabatay ang totoong halaga sa wage band at eligibility category.", "Ilagay ang buwanang insured wages sa MYR. Ang resulta ay simpleng 0.5% illustration lamang; hindi kasama ang employer share, EIS, o pagsusuri ng coverage.", "Kasalukuyang engine illustration = min(buwanang sahod, RM6,000) × 0.5%. Kinukuha ang statutory amount sa wage-band table ng PERKESO; hindi ito napapalitan ng simpleng porsiyento.", "Sa RM6,000 na sahod, RM30 ang ipinapakita ng engine. RM29.75 ang employee contribution sa PERKESO Act 4 band na lampas RM5,900 hanggang RM6,000. Illustration lang ang RM30, hindi wastong payroll deduction.", "Maaari ko ba itong gamitin sa payroll?", "Hindi. Hindi kinakatawan ng flat rate ang band rounding, category, o exemption. Gamitin ang kasalukuyang talahanayan o opisyal na employer calculator ng PERKESO."),
  },
  bn: {
    "malaysia-income-tax-calculator": c("এই মালয়েশীয় আয়কর ক্যালকুলেটর দেওয়া বার্ষিক করযোগ্য আয়ে ধাপে ধাপে করহার প্রয়োগ করে। ইঞ্জিনের হার LHDN-এর YA 2023–2025 সারণির সঙ্গে মেলে; যাচাই করা উৎস YA 2026 নিশ্চিত করে না। এটি কর-নিবাসীদের জন্য হারভিত্তিক উদাহরণ।", "প্রযোজ্য ছাড় জানা থাকলে তা বাদ দিয়ে বার্ষিক করযোগ্য আয় MYR-এ লিখুন। মোট বেতন লিখলে ব্যক্তিগত ছাড় বা রিবেট স্বয়ংক্রিয়ভাবে বাদ যায় না।", "প্রতিটি কর-সীমার অংশে প্রান্তিক হার প্রয়োগ করে যোগ করুন: প্রথম RM5,000-এ 0%, এরপর 1%, 3%, 6%, 11%, 19%, 25%, 26%, 28%, এবং RM2,000,000-এর বেশি অংশে 30%。", "YA 2025 সারণি অনুসারে RM100,000 করযোগ্য আয়ে কর RM9,400 এবং গড় হার 9.4%। ইঞ্জিনের ফল মেলে, তবে ব্যক্তিগত ছাড় বা রিবেট নেই।", "এটি কি 2026 সালের চূড়ান্ত কর?", "না। দেখা LHDN সারণি YA 2023–2025 দেখায়, YA 2026 নিশ্চিত করে না। কর-নিবাস, ছাড়, রিবেট এবং পরবর্তী পরিবর্তনও ইনপুটে নেই।"),
    "malaysia-epf-calculator": c("মালয়েশিয়ার EPF (KWSP) ক্যালকুলেটর মাসিক বেতন ও বিস্তৃত বয়স-গোষ্ঠী থেকে কর্মী এবং নিয়োগকর্তার অংশ অনুমান করে। ডিফল্ট হার কিছু প্রচলিত মালয়েশীয় সদস্য-শ্রেণির জন্য; নির্দিষ্ট বিদেশি কর্মীর ক্ষেত্রে অক্টোবর 2025-এর বেতন থেকে উভয় পক্ষের আলাদা 2% হার আছে।", "মাসিক বেতন MYR-এ লিখুন এবং 60 বছরের নিচে বা 60 ও তার বেশি বেছে নিন। নাগরিকত্ব, সদস্যতার ইতিহাস বা অব্যাহতি এখানে যাচাই হয় না।", "ইঞ্জিনে 60 বছরের নিচে কর্মীর হার 11%; নিয়োগকর্তার হার RM5,000 পর্যন্ত 13%, বেশি হলে 12%। 60 বা তার বেশি বয়সে কর্মী 5.5%, নিয়োগকর্তা 6.5%/6%。", "60 বছরের নিচে RM6,000 মাসিক বেতনে কর্মীর RM660 ও নিয়োগকর্তার RM720, মোট RM1,380 হয়। উদাহরণটি শুধু ওই অবদান-শ্রেণির জন্য।", "বিদেশি কর্মীর ক্ষেত্রেও কি একই হার?", "সবার ক্ষেত্রে নয়। KWSP নির্দিষ্ট অ-মালয়েশীয় কর্মীর জন্য অক্টোবর 2025-এর বেতন থেকে দুই পক্ষের 2% করে উল্লেখ করে। নাগরিকত্বের বিকল্প নেই, তাই সেই ক্ষেত্র এই ক্যালকুলেটর মডেল করে না।"),
    "malaysia-socso-calculator": c("এই SOCSO (PERKESO) পৃষ্ঠা আইনগত অবদান-সারণি ব্যবহার করে না। বর্তমান ইঞ্জিন RM6,000 বেতনসীমা পর্যন্ত কর্মীর 0.5% সরল হিসাব দেখায়; প্রকৃত অবদান বেতন-স্তর ও যোগ্যতার শ্রেণির ওপর নির্ভর করে।", "মাসিক insured wages MYR-এ লিখুন। ফলটি শুধু কর্মীর 0.5% উদাহরণ; নিয়োগকর্তার অংশ, EIS এবং কভারেজের যোগ্যতা এতে নেই।", "বর্তমান ইঞ্জিনের উদাহরণ = min(মাসিক বেতন, RM6,000) × 0.5%。 আইনগত অঙ্ক PERKESO-এর বেতন-স্তর সারণি থেকে নিতে হয়; এই সরল সূত্র তার বিকল্প নয়।", "RM6,000 বেতনে ইঞ্জিন RM30 দেখায়। PERKESO Act 4 সারণিতে RM5,900-এর বেশি থেকে RM6,000 পর্যন্ত স্তরে কর্মীর অংশ RM29.75। RM30 কেবল উদাহরণ, সঠিক payroll কর্তন নয়।", "এই ফল payroll-এ ব্যবহার করতে পারি?", "না। নির্দিষ্ট হার স্তরভিত্তিক rounding, শ্রেণি বা অব্যাহতি দেখায় না। payroll-এর জন্য PERKESO-এর বর্তমান সারণি বা নিয়োগকর্তার সরকারি ক্যালকুলেটর ব্যবহার করুন।"),
  },
  uk: {
    "malaysia-income-tax-calculator": c("Цей калькулятор податку на доходи Малайзії застосовує прогресивні діапазони до введеного річного оподатковуваного доходу. Ставки двигуна відповідають таблиці LHDN для YA 2023–2025; перевірене джерело не підтверджує правила YA 2026. Це приклад ставок для податкових резидентів.", "Введіть річний оподатковуваний дохід у MYR після відомих пільг. Якщо ввести валову зарплату, особисті пільги та знижки не віднімаються.", "Для кожного граничного діапазону помножте його частину доходу на ставку й складіть: 0% на перші RM5 000, далі 1%, 3%, 6%, 11%, 19%, 25%, 26%, 28% і 30% понад RM2 000 000.", "За таблицею YA 2025 дохід RM100 000 дає податок RM9 400 і середню ставку 9,4%. Результат двигуна збігається, але особисті пільги не враховані.", "Це мій остаточний податок за 2026 рік?", "Ні. Перевірена таблиця LHDN охоплює YA 2023–2025 і не підтверджує YA 2026. Податкове резидентство, пільги, знижки та наступні зміни не є входами калькулятора."),
    "malaysia-epf-calculator": c("Калькулятор EPF (KWSP) оцінює внески працівника й роботодавця за місячною зарплатою та широкою віковою групою. Типові ставки відповідають окремим категоріям громадян Малайзії; для деяких іноземних працівників із зарплати за жовтень 2025 року діють окремі частки по 2%.", "Введіть місячну зарплату в MYR і виберіть вік до 60 або від 60 років. Громадянство, історію участі та звільнення не запитують.", "Двигун використовує 11% працівника до 60 років; роботодавець — 13% до RM5 000 і 12% вище. З 60 років: 5,5% працівника та 6,5%/6% роботодавця.", "За зарплати RM6 000 і віку до 60 років виходить RM660 працівника й RM720 роботодавця, разом RM1 380. Це приклад лише для цієї категорії.", "Ці ставки застосовуються до іноземних працівників?", "Не до всіх. KWSP вказує для деяких немалайзійців по 2% з кожної сторони від зарплати за жовтень 2025 року. Поля громадянства немає, тому ці випадки не моделюються."),
    "malaysia-socso-calculator": c("Ця сторінка SOCSO (PERKESO) не реалізує встановлену законом таблицю внесків. Поточний двигун показує спрощені 0,5% працівника з обмеженням зарплати RM6 000; фактична сума залежить від діапазону зарплати, категорії та права на страхування.", "Введіть місячну страховану зарплату в MYR. Результат — лише ілюстрація 0,5% працівника; частка роботодавця, EIS і перевірка покриття не включені.", "Ілюстрація двигуна = min(місячна зарплата, RM6 000) × 0,5%. Законну суму беруть із таблиці діапазонів PERKESO; ця пропорція її не замінює.", "За RM6 000 двигун показує RM30. Таблиця PERKESO Act 4 вказує RM29,75 працівника для діапазону понад RM5 900 до RM6 000. RM30 — ілюстрація, а не правильне утримання.", "Можна використати результат для нарахування зарплати?", "Ні. Фіксований відсоток не відображає округлення за діапазонами, категорії або звільнення. Для зарплати використовуйте актуальну таблицю чи офіційний калькулятор PERKESO для роботодавців."),
  },
  ms: {
    "malaysia-income-tax-calculator": c("Kalkulator cukai pendapatan Malaysia ini mengenakan kadar progresif pada pendapatan bercukai tahunan yang dimasukkan. Jalur enjin sepadan dengan jadual LHDN bagi YA 2023–2025; sumber yang disemak tidak mengesahkan peraturan YA 2026. Anggap hasil sebagai contoh kadar untuk pemastautin.", "Masukkan pendapatan bercukai tahunan dalam MYR selepas pelepasan yang diketahui. Jika gaji kasar dimasukkan, pelepasan dan rebat peribadi tidak ditolak.", "Darabkan setiap bahagian pendapatan dalam jalur marginal dengan kadarnya lalu jumlahkan: 0% bagi RM5,000 pertama, kemudian 1%, 3%, 6%, 11%, 19%, 25%, 26%, 28% dan 30% bagi lebihan RM2,000,000.", "Pendapatan bercukai RM100,000 menghasilkan cukai RM9,400 dan kadar purata 9.4% mengikut jadual YA 2025. Enjin sepadan tetapi tidak mengambil kira pelepasan atau rebat peribadi.", "Adakah ini cukai akhir saya bagi 2026?", "Tidak. Jadual LHDN yang disemak menyenaraikan YA 2023–2025 dan tidak mengesahkan YA 2026. Status pemastautin, pelepasan, rebat dan perubahan kemudian juga tiada dalam input."),
    "malaysia-epf-calculator": c("Kalkulator EPF (KWSP) Malaysia menganggarkan bahagian pekerja dan majikan daripada gaji bulanan serta kumpulan umur yang luas. Kadar lalai sepadan dengan beberapa kategori pekerja Malaysia yang lazim; pekerja asing tertentu mempunyai kadar 2% berasingan bagi setiap pihak untuk gaji mulai Oktober 2025.", "Masukkan gaji bulanan dalam MYR dan pilih bawah 60 atau 60 tahun ke atas. Kewarganegaraan, sejarah keahlian dan pengecualian tidak ditanya.", "Enjin menggunakan 11% pekerja bawah 60 tahun; majikan 13% sehingga RM5,000 dan 12% selepasnya. Umur 60 ke atas: pekerja 5.5%, majikan 6.5%/6%.", "Pada gaji RM6,000 dan umur bawah 60 tahun, hasilnya RM660 pekerja dan RM720 majikan, jumlah RM1,380. Contoh ini hanya untuk kategori caruman tersebut.", "Adakah kadar ini sama untuk pekerja asing?", "Bukan semuanya. KWSP menyatakan pekerja bukan Malaysia tertentu mempunyai bahagian 2% setiap pihak mulai gaji Oktober 2025. Tiada pilihan kewarganegaraan, jadi kalkulator ini tidak memodelkan kes tersebut."),
    "malaysia-socso-calculator": c("Halaman SOCSO (PERKESO) ini tidak melaksanakan jadual caruman berkanun. Enjin semasa hanya menunjukkan kiraan ringkas 0.5% bahagian pekerja dengan had gaji RM6,000; jumlah sebenar bergantung pada jalur gaji, kategori dan kelayakan.", "Masukkan gaji bulanan yang diinsuranskan dalam MYR. Hasilnya hanya ilustrasi 0.5% pekerja; bahagian majikan, EIS dan semakan perlindungan tidak termasuk.", "Ilustrasi enjin semasa = min(gaji bulanan, RM6,000) × 0.5%. Jumlah berkanun ditentukan melalui jadual jalur gaji PERKESO; formula berkadar ini bukan penggantinya.", "Pada RM6,000, enjin menunjukkan RM30. Jadual PERKESO Act 4 menyenaraikan RM29.75 bahagian pekerja bagi jalur melebihi RM5,900 hingga RM6,000. RM30 ialah ilustrasi, bukan potongan gaji yang tepat.", "Bolehkah hasil ini digunakan untuk potongan gaji?", "Tidak. Kadar rata tidak mencerminkan pembundaran jalur, kategori atau pengecualian. Gunakan jadual semasa atau kalkulator majikan rasmi PERKESO untuk penggajian."),
  },
  sv: {
    "malaysia-income-tax-calculator": c("Den här malaysiska inkomstskattekalkylatorn tillämpar progressiva skikt på den angivna årliga beskattningsbara inkomsten. Motorns skikt motsvarar LHDN-tabellen för YA 2023–2025; den granskade källan fastställer inte YA 2026. Se det som en skatteillustration för bosatta.", "Ange årlig beskattningsbar inkomst i MYR efter kända avdrag. Om bruttolön anges dras personliga lättnader och skattereduktioner inte av.", "Multiplicera varje del av inkomsten i ett marginalskikt med skattesatsen och summera: 0 % på de första RM5 000, därefter 1, 3, 6, 11, 19, 25, 26, 28 och 30 % över RM2 000 000.", "Vid RM100 000 beskattningsbar inkomst ger YA 2025-tabellen RM9 400 i skatt och 9,4 % genomsnittlig skattesats. Motorn stämmer men räknar inte med personliga lättnader eller rabatter.", "Är detta min slutliga skatt för 2026?", "Nej. Den granskade LHDN-tabellen omfattar YA 2023–2025 och bekräftar inte YA 2026. Skatterättslig hemvist, lättnader, rabatter och senare ändringar ingår inte heller."),
    "malaysia-epf-calculator": c("Malaysias EPF-kalkylator (KWSP) uppskattar arbetstagarens och arbetsgivarens andelar från månadslön och en bred åldersgrupp. Standardnivåerna passar vanliga malaysiska medlemskategorier; vissa utländska arbetstagare har separata andelar på 2 % vardera för lön från oktober 2025.", "Ange månadslön i MYR och välj under 60 eller minst 60 år. Medborgarskap, tidigare medlemskap och undantag efterfrågas inte.", "Motorn använder 11 % för arbetstagare under 60; arbetsgivaren betalar 13 % upp till RM5 000 och 12 % över det. Från 60 år: 5,5 % arbetstagare och 6,5/6 % arbetsgivare.", "Vid RM6 000 i månadslön och under 60 år blir arbetstagarandelen RM660 och arbetsgivarandelen RM720, totalt RM1 380. Exemplet gäller bara den kategorin.", "Gäller dessa nivåer även utländska arbetstagare?", "Inte alla. KWSP anger separata andelar på 2 % för vissa icke-malaysiska arbetstagare från löner för oktober 2025. Kalkylatorn saknar medborgarskapsval och omfattar inte dessa fall."),
    "malaysia-socso-calculator": c("Den här SOCSO-sidan (PERKESO) använder inte den lagstadgade avgiftstabellen. Motorn visar en förenklad arbetstagarandel på 0,5 % med lönetak RM6 000; det faktiska beloppet beror på löneklass, kategori och behörighet.", "Ange månatlig försäkrad lön i MYR. Resultatet illustrerar endast arbetstagarens 0,5 %; arbetsgivarandel, EIS och försäkringsskydd ingår inte.", "Motorns illustration = min(månadslön, RM6 000) × 0,5 %. Det lagstadgade beloppet hämtas ur PERKESOs löneklass-tabell; den proportionella formeln ersätter den inte.", "Vid RM6 000 visar motorn RM30. PERKESO Act 4-tabellen anger RM29,75 i arbetstagaravgift för intervallet över RM5 900 till RM6 000. RM30 är en illustration, inte ett korrekt löneavdrag.", "Kan jag använda beloppet som löneavdrag?", "Nej. En fast procentsats återger inte klassernas avrundning, kategorier eller undantag. Använd PERKESOs aktuella tabell eller officiella arbetsgivarkalkylator för löner."),
  },
  cs: {
    "malaysia-income-tax-calculator": c("Tato malajsijská kalkulačka daně z příjmu uplatňuje progresivní pásma na zadaný roční zdanitelný příjem. Pásma odpovídají tabulce LHDN pro YA 2023–2025; ověřený zdroj nepotvrzuje pravidla YA 2026. Jde o ilustraci sazeb pro daňové rezidenty.", "Zadejte roční zdanitelný příjem v MYR po známých úlevách. Při zadání hrubé mzdy se osobní úlevy ani slevy automaticky neodečtou.", "Sečtěte části příjmu v jednotlivých mezních pásmech: 0 % z prvních RM5 000, dále 1 %, 3 %, 6 %, 11 %, 19 %, 25 %, 26 %, 28 % a 30 % z částky nad RM2 000 000.", "Při zdanitelném příjmu RM100 000 dává tabulka YA 2025 daň RM9 400 a průměrnou sazbu 9,4 %. Výpočet motoru souhlasí, ale nezahrnuje osobní úlevy ani slevy.", "Je to moje konečná daň za rok 2026?", "Ne. Ověřená tabulka LHDN uvádí YA 2023–2025 a nepotvrzuje YA 2026. Daňová rezidence, úlevy, slevy a pozdější změny navíc nejsou vstupy kalkulačky."),
    "malaysia-epf-calculator": c("Malajsijská kalkulačka EPF (KWSP) odhaduje podíly zaměstnance a zaměstnavatele z měsíční mzdy a široké věkové skupiny. Výchozí sazby odpovídají běžným kategoriím malajsijských zaměstnanců; někteří zahraniční pracovníci mají od mzdy za říjen 2025 zvláštní sazbu 2 % pro každou stranu.", "Zadejte měsíční mzdu v MYR a vyberte věk pod 60 nebo od 60 let. Občanství, historie členství ani výjimky se nezjišťují.", "Motor používá do 60 let 11 % zaměstnanec; zaměstnavatel 13 % do RM5 000 a 12 % nad tuto částku. Od 60 let: zaměstnanec 5,5 %, zaměstnavatel 6,5/6 %.", "Při mzdě RM6 000 a věku pod 60 let vychází RM660 zaměstnanec a RM720 zaměstnavatel, celkem RM1 380. Příklad platí pouze pro tuto kategorii.", "Platí tyto sazby i pro zahraniční zaměstnance?", "Ne pro všechny. KWSP uvádí u některých pracovníků bez malajsijského občanství 2 % na každé straně od mzdy za říjen 2025. Kalkulačka občanství nerozlišuje."),
    "malaysia-socso-calculator": c("Tato stránka SOCSO (PERKESO) nepočítá zákonnou tabulku příspěvků. Současný motor ukazuje jen zjednodušených 0,5 % zaměstnance s limitem mzdy RM6 000; skutečná částka závisí na mzdovém pásmu, kategorii a nároku.", "Zadejte měsíční pojištěnou mzdu v MYR. Výsledek je pouze ilustrace 0,5 % zaměstnance; podíl zaměstnavatele, EIS ani posouzení krytí nejsou zahrnuty.", "Ilustrace motoru = min(měsíční mzda, RM6 000) × 0,5 %. Zákonná částka se určuje z tabulky mzdových pásem PERKESO; tento poměrný vzorec ji nenahrazuje.", "Při RM6 000 ukáže motor RM30. Tabulka PERKESO Act 4 uvádí příspěvek zaměstnance RM29,75 pro pásmo nad RM5 900 do RM6 000. RM30 je ilustrace, nikoli správná srážka ze mzdy.", "Mohu výsledek použít pro mzdy?", "Ne. Pevné procento nezachycuje zaokrouhlení pásem, kategorie ani výjimky. Pro mzdy použijte aktuální tabulku nebo oficiální kalkulačku zaměstnavatele PERKESO."),
  },
  ro: {
    "malaysia-income-tax-calculator": c("Acest calculator de impozit pe venit din Malaysia aplică tranșe progresive venitului anual impozabil introdus. Tranșele motorului corespund tabelului LHDN pentru YA 2023–2025; sursa verificată nu confirmă regulile YA 2026. Rezultatul este o ilustrare a cotelor pentru rezidenți fiscali.", "Introduceți venitul anual impozabil în MYR după deducerile cunoscute. Dacă introduceți salariul brut, facilitățile și reducerile personale nu sunt scăzute.", "Înmulțiți fiecare parte a venitului din tranșa marginală cu cota ei și adunați: 0% pentru primii RM5.000, apoi 1%, 3%, 6%, 11%, 19%, 25%, 26%, 28% și 30% pentru partea peste RM2.000.000.", "La RM100.000 venit impozabil, tabelul YA 2025 produce RM9.400 impozit și o cotă medie de 9,4%. Motorul se potrivește, dar nu aplică facilități sau reduceri personale.", "Este acesta impozitul meu final pentru 2026?", "Nu. Tabelul LHDN verificat arată YA 2023–2025 și nu confirmă YA 2026. Rezidența fiscală, facilitățile, reducerile și modificările ulterioare nu sunt intrări ale calculatorului."),
    "malaysia-epf-calculator": c("Calculatorul EPF (KWSP) din Malaysia estimează părțile angajatului și angajatorului din salariul lunar și o grupă largă de vârstă. Ratele implicite corespund unor categorii obișnuite de angajați malaysieni; unii lucrători străini au cote separate de 2% pentru fiecare parte începând cu salariile din octombrie 2025.", "Introduceți salariul lunar în MYR și selectați sub 60 sau cel puțin 60 de ani. Cetățenia, istoricul de membru și scutirile nu sunt solicitate.", "Motorul folosește 11% angajat sub 60 de ani; angajatorul 13% până la RM5.000 și 12% peste. De la 60 de ani: 5,5% angajat și 6,5%/6% angajator.", "La salariu lunar RM6.000 și sub 60 de ani, rezultatul este RM660 angajat și RM720 angajator, în total RM1.380. Exemplul este doar pentru acea categorie.", "Se aplică aceleași cote lucrătorilor străini?", "Nu tuturor. KWSP menționează pentru unii angajați non-malaysieni câte 2% pentru fiecare parte de la salariile din octombrie 2025. Calculatorul nu are opțiune de cetățenie."),
    "malaysia-socso-calculator": c("Această pagină SOCSO (PERKESO) nu implementează tabelul legal de contribuții. Motorul actual arată doar un calcul simplu de 0,5% pentru angajat, cu plafon salarial RM6.000; suma reală depinde de tranșă, categorie și eligibilitate.", "Introduceți salariul lunar asigurat în MYR. Rezultatul ilustrează doar 0,5% pentru angajat; partea angajatorului, EIS și eligibilitatea nu sunt incluse.", "Ilustrația motorului = min(salariul lunar, RM6.000) × 0,5%. Suma legală se ia din tranșele salariale PERKESO; formula proporțională nu le înlocuiește.", "La RM6.000, motorul afișează RM30. Tabelul PERKESO Act 4 indică RM29,75 contribuție a angajatului pentru tranșa peste RM5.900 până la RM6.000. RM30 este o ilustrare, nu o reținere salarială corectă.", "Pot folosi suma pentru salarizare?", "Nu. Procentul fix nu reflectă rotunjirea pe tranșe, categoriile sau scutirile. Pentru salarizare consultați tabelul actual ori calculatorul oficial PERKESO pentru angajatori."),
  },
  el: {
    "malaysia-income-tax-calculator": c("Αυτός ο μαλαισιανός υπολογιστής φόρου εισοδήματος εφαρμόζει προοδευτικές κλίμακες στο ετήσιο φορολογητέο εισόδημα που εισάγετε. Οι κλίμακες του μηχανισμού συμφωνούν με τον πίνακα LHDN για YA 2023–2025· η πηγή που ελέγχθηκε δεν επιβεβαιώνει τους κανόνες YA 2026. Πρόκειται για ενδεικτικό υπολογισμό για φορολογικούς κατοίκους.", "Εισαγάγετε το ετήσιο φορολογητέο εισόδημα σε MYR μετά από γνωστές εκπτώσεις. Αν εισαγάγετε μικτό μισθό, δεν αφαιρούνται προσωπικές εκπτώσεις ή πιστώσεις.", "Πολλαπλασιάστε κάθε τμήμα εισοδήματος της οριακής κλίμακας με τον συντελεστή και αθροίστε: 0% στα πρώτα RM5.000, έπειτα 1%, 3%, 6%, 11%, 19%, 25%, 26%, 28% και 30% πάνω από RM2.000.000.", "Για φορολογητέο εισόδημα RM100.000, ο πίνακας YA 2025 δίνει φόρο RM9.400 και μέσο συντελεστή 9,4%. Ο μηχανισμός συμφωνεί, αλλά δεν εφαρμόζει προσωπικές εκπτώσεις ή επιστροφές.", "Είναι αυτός ο τελικός φόρος μου για το 2026;", "Όχι. Ο ελεγμένος πίνακας LHDN εμφανίζει YA 2023–2025 και δεν επιβεβαιώνει YA 2026. Η φορολογική κατοικία, οι εκπτώσεις, οι επιστροφές και μεταγενέστερες αλλαγές δεν είναι είσοδοι."),
    "malaysia-epf-calculator": c("Ο μαλαισιανός υπολογιστής EPF (KWSP) εκτιμά τα μερίδια εργαζομένου και εργοδότη από τον μηνιαίο μισθό και μια ευρεία ηλικιακή ομάδα. Οι προεπιλεγμένοι συντελεστές ισχύουν για συνήθεις κατηγορίες Μαλαισιανών· ορισμένοι αλλοδαποί εργαζόμενοι έχουν ξεχωριστό 2% ανά πλευρά για μισθούς από τον Οκτώβριο 2025.", "Εισαγάγετε μηνιαίο μισθό σε MYR και επιλέξτε κάτω από 60 ή από 60 ετών. Δεν ζητούνται υπηκοότητα, ιστορικό συμμετοχής ή εξαιρέσεις.", "Ο μηχανισμός χρησιμοποιεί 11% εργαζομένου κάτω των 60· εργοδότη 13% έως RM5.000 και 12% πάνω από αυτό. Από τα 60: 5,5% εργαζομένου και 6,5%/6% εργοδότη.", "Με RM6.000 μηνιαίως και ηλικία κάτω των 60, υπολογίζονται RM660 εργαζομένου και RM720 εργοδότη, σύνολο RM1.380. Το παράδειγμα αφορά μόνο αυτή την κατηγορία.", "Ισχύουν αυτά τα ποσοστά για αλλοδαπούς εργαζομένους;", "Όχι για όλους. Η KWSP αναφέρει για ορισμένους μη Μαλαισιανούς 2% από κάθε πλευρά για μισθούς Οκτωβρίου 2025 και μετά. Δεν υπάρχει επιλογή υπηκοότητας, άρα αυτές οι περιπτώσεις δεν μοντελοποιούνται."),
    "malaysia-socso-calculator": c("Αυτή η σελίδα SOCSO (PERKESO) δεν εφαρμόζει τον νόμιμο πίνακα εισφορών. Ο τρέχων μηχανισμός δείχνει μόνο απλό 0,5% εργαζομένου με όριο μισθού RM6.000· το πραγματικό ποσό εξαρτάται από μισθολογική κλίμακα, κατηγορία και επιλεξιμότητα.", "Εισαγάγετε τον μηνιαίο ασφαλισμένο μισθό σε MYR. Το αποτέλεσμα είναι μόνο ενδεικτικό 0,5% εργαζομένου· δεν περιλαμβάνει εργοδοτικό μερίδιο, EIS ή έλεγχο κάλυψης.", "Ενδεικτικό αποτέλεσμα μηχανισμού = min(μηνιαίος μισθός, RM6.000) × 0,5%. Το νόμιμο ποσό προκύπτει από τις μισθολογικές κλίμακες PERKESO· ο αναλογικός τύπος δεν τις αντικαθιστά.", "Στα RM6.000 ο μηχανισμός δείχνει RM30. Ο πίνακας PERKESO Act 4 αναφέρει RM29,75 εργαζομένου για κλίμακα πάνω από RM5.900 έως RM6.000. Τα RM30 είναι ενδεικτικά, όχι σωστή παρακράτηση μισθού.", "Μπορώ να χρησιμοποιήσω το ποσό για μισθοδοσία;", "Όχι. Το σταθερό ποσοστό δεν αποτυπώνει στρογγυλοποίηση κλίμακας, κατηγορίες ή εξαιρέσεις. Για μισθοδοσία χρησιμοποιήστε τον τρέχοντα πίνακα ή τον επίσημο εργοδοτικό υπολογιστή PERKESO."),
  },
};
